"""Vendor the reviewed EQ Eight model/renderer, excluding its local controller."""
import argparse,hashlib,json,shutil,subprocess
from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);a=p.parse_args()
out=root/'web/device-renderers/eq8';out.mkdir(parents=True,exist_ok=True);hashes={}
for name in ['model.js','device.js','svg.js']:
 text=(a.source/name).read_text();hashes[name]=hashlib.sha256(text.encode()).hexdigest()
 if name=='device.js':text=text.replace('const inactiveD=curvePath(inactiveBands,parameters,inactiveView);',"const inactiveD=mode==='Stereo'?'':curvePath(inactiveBands,parameters,inactiveView);")
 (out/name).write_text(text)
(out/'index.js').write_text("export {renderDevice} from './device.js';\nexport * from './model.js';\n")
(out/'provenance.json').write_text(json.dumps({'source':'EQ Eight independent remake, 131 reference states','files':hashes,'omitted':['local controller and synthetic IDs','comparison/ranking harness','capture assets','network transport']},indent=2)+'\n')
state=json.loads((a.source.parent/'states/001-flat-all-disabled.json').read_text());spec={'id':'eq-eight','className':'Eq8','bindings':[{k:p[k] for k in ('name','min','max','quantized','items')} for p in state['parameters']]}
(root/'web/eq8-signature.js').write_text('// Generated by tools/sync_eq8_renderer.py.\nconst EQ8Signature='+json.dumps(spec,separators=(',',':'))+';\n')
subprocess.run([str(root/'node_modules/.bin/esbuild'),str(out/'index.js'),'--bundle','--format=iife','--global-name=EQ8Renderer','--target=es2020','--outfile='+str(root/'web/eq8-renderer.js')],check=True)
